package com.cpf.starter.integration.graphql;
import java.util.Locale; import reactor.core.publisher.Mono; import org.springframework.graphql.server.*;
public final class CpfGraphqlGuardInterceptor implements WebGraphQlInterceptor { private final CpfGraphqlProperties p; public CpfGraphqlGuardInterceptor(CpfGraphqlProperties p){this.p=p;} @Override public Mono<WebGraphQlResponse> intercept(WebGraphQlRequest request,Chain chain){String doc=request.getDocument(); if(doc!=null&&doc.length()>p.getMaxDocumentLength())return Mono.error(new IllegalArgumentException("GraphQL document too large")); if(!p.isIntrospection()&&doc!=null&&doc.toLowerCase(Locale.ROOT).contains("__schema"))return Mono.error(new IllegalArgumentException("GraphQL introspection disabled")); return chain.next(request);} }
